void AdaptiveSession::assemble_trace_mating(HybridTraceEvent& trace) {
        trace.de_mating_local_count = run_.last_mating_stats.local;
        trace.de_mating_global_count = run_.last_mating_stats.global;
        trace.de_mating_fallback_count = run_.last_mating_stats.fallback;
        trace.de_mating_key_unknown_count = run_.last_mating_stats.key_unknown;
        trace.de_mating_archive_local_count = run_.last_mating_stats.archive_local;
        trace.de_mating_archive_global_count = run_.last_mating_stats.archive_global;
        trace.de_mating_local_pool_min = run_.last_mating_stats.local_pool_min;
        trace.de_mating_local_pool_max = run_.last_mating_stats.local_pool_max;
        if (run_.last_mating_stats.local_pool_samples > 0) {
            trace.de_mating_local_pool_mean =
                static_cast<double>(run_.last_mating_stats.local_pool_sum) /
                static_cast<double>(run_.last_mating_stats.local_pool_samples);
        }
}


